glsl:
/////////////////////////////////////////////////////////
// Alpha cutoff effect
// NOTE: this effect is essentially a broken 'Alpha clamp' effect.
// It accidentally multiplies the premultiplied RGB by the clamped
// alpha again, essentially meaning the RGB is premultiplied twice over.
// That causes a darkening effect towards the edges as the alpha
// reduces. The effect was originally named 'Alpha clamp' and widely
// used for years, so changing it causes an awkward backward compatibility
// problem. Therefore the legacy alpha clamp effect is left as-is but 
// renamed to "Alpha cutoff"; the alphaclamp2 effect is a new effect
// that works correctly and is named "Alpha clamp", taking the old name.
precision mediump float;
varying mediump vec2 vTex;
uniform lowp sampler2D samplerFront;
uniform lowp float alphathreshold;
uniform lowp float lowerclamp;
uniform lowp float upperclamp;

void main(void)
{
	// Retrieve source pixel
	lowp vec4 front = texture2D(samplerFront, vTex);
	
	// Extract alpha
	lowp float a = front.a;

	// Mistake: this code was in the original shader, but it
	// does not actually use the unpremultiplied RGB value.
	//lowp vec4 unpremultiplied = front / a;
	
	// Apply threshold
	a = (a < alphathreshold ? lowerclamp : upperclamp);
	
	// Premultiply the RGB a second time (incorrect!) and then
	// assign the clamped alpha.
	front *= a;
	front.a = a;
	
	gl_FragColor = front;
}

wgsl:
/////////////////////////////////////////////////////////
// Texture and sampler
%%SAMPLERFRONT_BINDING%% var samplerFront : sampler;
%%TEXTUREFRONT_BINDING%% var textureFront : texture_2d<f32>;

/////////////////////////////////////////////////////////
// Shader custom parameters
struct ShaderParams {
	alphathreshold : f32,
	lowerclamp : f32,
	upperclamp : f32
};
%%SHADERPARAMS_BINDING%% var<uniform> shaderParams : ShaderParams;

%%C3_UTILITY_FUNCTIONS%%

%%FRAGMENTINPUT_STRUCT%%
%%FRAGMENTOUTPUT_STRUCT%%

/////////////////////////////////////////////////////////
// Main method
@fragment
fn main(input : FragmentInput) -> FragmentOutput
{
	// Retrieve source pixel
	var front : vec4<f32> = textureSample(textureFront, samplerFront, input.fragUV);

	// Apply alpha threshold
	front.a = select(shaderParams.upperclamp, shaderParams.lowerclamp, front.a < shaderParams.alphathreshold);

	// Output premultiplied a second time. NOTE: this is replicating the same mistake
	// the WebGL shader makes for compatibility.
	var output : FragmentOutput;
	output.color = vec4<f32>(front.rgb * front.a, front.a);
	return output;
}

